public class Foo {
    int add(int a, int b) {
        return a + b;
    }
}

public class Foo {
    int sub(int a, int b) {
        return a - b;
    }

    long mul(long a, long b) {
        return a * b;
    }

    long mixed(int a, long b) {
        return a + b;
    }

    int offset(char c) {
        return c - 'a';
    }
}

public class Foo {
    long m(int a, long b) {
        long total = 0;
        total += a;
        total -= b;
        total *= 2;
        return total;
    }
}

public class Foo {
    int negate(int a) {
        return -a;
    }

    long distance(long a) {
        return Math.abs(a);
    }

    int magnitude(int b) {
        return Math.abs(b);
    }
}

public class Foo {
    void m(int[] a) {
        for (int i = 0; i < a.length - 1; i += 2) {
            System.out.println(a[i]);
        }
    }
}

public class Foo {
    static final int SIZE = 4 * 1024;
    static final long LIMIT = -1L;

    int exact(int a, int b) {
        return Math.multiplyExact(Math.addExact(a, b), Math.negateExact(b));
    }

    void increments(int i) {
        i++;
        --i;
    }

    int divide(int a, int b) {
        return a / b % 3;
    }

    String text(int a) {
        String s = "value " + a;
        s += a;
        return s;
    }

    double real(double x, float y) {
        return -x + y * 2 - Math.abs(x);
    }
}
